import React, { useEffect, useState, useRef } from "react";
import { useParams, useNavigate } from "react-router-dom";
import axios from "axios";
import { io } from "socket.io-client";
import { useAuth } from "../context/AuthContext";
import "./Chat.css";

let socket;

export default function Chat() {
  const { userId } = useParams();
  const { user } = useAuth();
  const navigate = useNavigate();
  const [conversations, setConversations] = useState([]);
  const [messages, setMessages] = useState([]);
  const [activeUser, setActiveUser] = useState(null);
  const [input, setInput] = useState("");
  const [loading, setLoading] = useState(false);
  const bottomRef = useRef(null);

  // Connect socket
  useEffect(() => {
    socket = io("http://localhost:5000");
    socket.emit("join", user._id);

    socket.on("receiveMessage", ({ senderId, message, timestamp }) => {
      setMessages((prev) => [...prev, { sender: { _id: senderId }, content: message, createdAt: timestamp }]);
    });

    return () => socket.disconnect();
  }, [user._id]);

  // Load conversations
  useEffect(() => {
    axios.get("/api/messages").then((res) => setConversations(res.data));
  }, []);

  // Load messages for a user
  const openConversation = async (targetUser) => {
    setActiveUser(targetUser);
    setLoading(true);
    navigate(`/chat/${targetUser._id}`);
    const { data } = await axios.get(`/api/messages/${targetUser._id}`);
    setMessages(data);
    setLoading(false);
  };

  // Auto-open from URL param
  useEffect(() => {
    if (userId && userId !== activeUser?._id) {
      axios.get(`/api/users/${userId}`).then((res) => openConversation(res.data));
    }
  }, [userId]);

  // Scroll to bottom
  useEffect(() => {
    bottomRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages]);

  const sendMessage = async () => {
    if (!input.trim() || !activeUser) return;
    const content = input.trim();
    setInput("");

    // Optimistic update
    setMessages((prev) => [
      ...prev,
      { sender: { _id: user._id }, content, createdAt: new Date() },
    ]);

    await axios.post("/api/messages", { receiverId: activeUser._id, content });

    // Emit socket
    socket.emit("sendMessage", { senderId: user._id, receiverId: activeUser._id, message: content });
  };

  const handleKey = (e) => {
    if (e.key === "Enter" && !e.shiftKey) { e.preventDefault(); sendMessage(); }
  };

  return (
    <div className="chat-page">
      {/* Sidebar */}
      <div className="chat-sidebar">
        <div className="chat-sidebar-header">
          <h3>Messages</h3>
        </div>
        {conversations.length === 0 ? (
          <div className="chat-empty-sidebar">
            <p>No conversations yet.</p>
            <p style={{ fontSize: 12 }}>Start by messaging a mentor!</p>
          </div>
        ) : (
          conversations.map(({ partner, lastMessage }) => (
            <div key={partner._id} className={`conv-item ${activeUser?._id === partner._id ? "active" : ""}`}
              onClick={() => openConversation(partner)}>
              <div className="conv-avatar">{partner.name?.[0]}</div>
              <div className="conv-info">
                <div className="conv-name">{partner.name}</div>
                <div className="conv-last">{lastMessage?.content?.slice(0, 30)}...</div>
              </div>
              <div className={`role-badge ${partner.role}`} style={{ fontSize: 10, padding: "2px 6px" }}>
                {partner.role}
              </div>
            </div>
          ))
        )}
      </div>

      {/* Chat area */}
      <div className="chat-main">
        {!activeUser ? (
          <div className="chat-placeholder">
            <span>💬</span>
            <h3>Select a conversation</h3>
            <p>Choose from your conversations or start a new one from a mentor's profile.</p>
          </div>
        ) : (
          <>
            <div className="chat-header">
              <div className="conv-avatar">{activeUser.name?.[0]}</div>
              <div>
                <div className="chat-header-name">{activeUser.name}</div>
                <div className="chat-header-role">{activeUser.role} • {activeUser.domain}</div>
              </div>
            </div>

            <div className="messages-area">
              {loading ? <div className="spinner" /> :
                messages.length === 0 ? (
                  <div className="no-messages">Send a message to start the conversation!</div>
                ) : (
                  messages.map((msg, i) => {
                    const isMe = msg.sender?._id === user._id || msg.sender === user._id;
                    return (
                      <div key={i} className={`message-wrap ${isMe ? "me" : "them"}`}>
                        {!isMe && <div className="msg-avatar">{activeUser.name?.[0]}</div>}
                        <div className={`message-bubble ${isMe ? "me" : "them"}`}>
                          {msg.content}
                          <div className="msg-time">
                            {new Date(msg.createdAt).toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" })}
                          </div>
                        </div>
                      </div>
                    );
                  })
                )
              }
              <div ref={bottomRef} />
            </div>

            <div className="chat-input-area">
              <textarea
                className="chat-input"
                rows={1}
                placeholder="Type a message... (Enter to send)"
                value={input}
                onChange={(e) => setInput(e.target.value)}
                onKeyDown={handleKey}
              />
              <button className="btn-primary send-btn" onClick={sendMessage}>Send ↑</button>
            </div>
          </>
        )}
      </div>
    </div>
  );
}
